import{_ as i,a0 as l,w as o,s as p,ao as c,I as d,x as a,a1 as t,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"通過示例來學習 Bash base64 的編碼和解碼 | LCTT x X-CMD","titleTemplate":false,"description":"通過示例來學習 Bash base64 的編碼和解碼 | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"通過示例來學習 Bash base64 的編碼和解碼 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"通過示例來學習 Bash base64 的編碼和解碼 | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20221013 Learn Bash base64 Encode and Decode With Examples","title":"通過示例來學習 Bash base64 的編碼和解碼","tag":"202210","desc":""},"relativePath":"202210/20221013 Learn Bash base64 Encode and Decode With Examples.md","filePath":"[post].md"}'),r={name:"202210/20221013 Learn Bash base64 Encode and Decode With Examples.md"};function h(b,e,g,u,m,k){const s=l("Link");return o(),p("div",null,[e[18]||(e[18]=c(`<h1 id="通過示例來學習-bash-base64-的編碼和解碼" tabindex="-1">通過示例來學習 Bash base64 的編碼和解碼 <a class="header-anchor" href="#通過示例來學習-bash-base64-的編碼和解碼" aria-label="Permalink to “通過示例來學習 Bash base64 的編碼和解碼”">​</a></h1><blockquote><p>你想了解 Base64 編碼和解碼的方法嗎？在本教程中，我們使用 Bash shell 腳本和各種示例解釋了 Base64 編碼和解碼步驟。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202210/29/163350mde5lll86j6lspln.jpg" alt=""></p><p>Base64 編碼方法可以將二進制數據轉換為文本，如此編碼數據可以在任何通信媒介進行傳輸。這種編碼方法主要用於電子郵件加密的過程。</p><p>總體而言，Base64 編碼方法是一種二進制到文本的編碼方案，以 ASCII 字符串格式表示 8 字節的二進制數據。使用這種編碼方法在各種媒介之間傳輸數據時有幾個優勢，尤其是對於那些能可靠地支持文本內容的媒介。因此，Base64 編碼方法在萬維網上被廣泛使用。這種編碼方案最常用於電子郵件附件的編碼上。</p><p>根據 Base64 編碼表，二進制數據可以經 Base64 編碼後可以轉換為 64 個不同的 ASCII 字符，包含大寫字母 <code>A</code> 到 <code>Z</code>，小寫字母 <code>a</code> 到 <code>z</code>，數字 <code>0</code> 到 <code>9</code>，以及符號 <code>+</code> 和 <code>/</code>，這些字符在傳輸和打印上十分便捷。</p><p>這 64 個 ASCII 字符代表着從 <code>000000</code> 到 <code>111111</code> 的二進制值。每個非末尾的 Base64 編碼字符恰好代表 6 位二進制值。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/11/Base64-Index-Table.png" alt="Base64 Index Table"></p><h3 id="bash-base64-的編碼和解碼" tabindex="-1">Bash base64 的編碼和解碼 <a class="header-anchor" href="#bash-base64-的編碼和解碼" aria-label="Permalink to “Bash base64 的編碼和解碼”">​</a></h3><h4 id="句法" tabindex="-1">句法 <a class="header-anchor" href="#句法" aria-label="Permalink to “句法”">​</a></h4><p>在我們提供示例之前，首先介紹 Base64 的基本語法。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>base64 [OPTIONs] [INFILE] [OUTFILE]</span></span></code></pre></div><ul><li>選項（<code>Option</code>）：參照下面的表格，你可以提供任何的選項或組合多個選項。</li><li>輸入（<code>INFILE</code>）：你可以從標準輸入（如命令列）或文件中輸入。</li><li>輸出（<code>OUTFILE</code>）：你可以將輸出重定向到標準輸出，如終端或文件中。</li></ul><div class="table-wrap"><table><thead><tr><th style="text-align:left;">選項</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>-e</code> 或者 <code>--encode</code></td><td style="text-align:left;">此選項用於對標準輸入的數據或從文件中讀入的數據進行編碼。這是默認選項。</td></tr><tr><td style="text-align:left;"><code>-d</code> 或者 <code>--decode</code></td><td style="text-align:left;">此選項用於對標準輸入的數據或從文件中讀入的已 Base64 編碼數據進行解碼。</td></tr><tr><td style="text-align:left;"><code>-n</code> 或者 <code>--noerrcheck</code></td><td style="text-align:left;">默認情況下，Base64 在解碼數據時，會自動檢查是否有錯誤。你可以使用該選項在解碼時忽略檢查。</td></tr><tr><td style="text-align:left;"><code>-i</code> 或 <code>--ignore-garbage</code></td><td style="text-align:left;">此選項用於在解碼時忽略非字母字符。</td></tr><tr><td style="text-align:left;"><code>-u</code> 或者 <code>--help</code></td><td style="text-align:left;">此選項用於獲取有關使用此命令的信息。</td></tr></tbody></table></div><h4 id="示例-1-基本編碼" tabindex="-1">示例 1：基本編碼 <a class="header-anchor" href="#示例-1-基本編碼" aria-label="Permalink to “示例 1：基本編碼”">​</a></h4><p>在 Linux 中，默認已安裝好 Base64 軟件包。因此，你可以輕鬆地從命令列使用 Base64。要對一個字符串或文本進行編碼，你可以通過管道將其傳遞到 <code>base64</code> 命令，並獲取待編碼的文本。在下面的示例中，對字符串 <code>debugpoint.com</code> 進行了 Base64 編碼。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo &quot;debugpoint.com&quot; | base64</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/11/bash-base64-encode-and-decode-example-1.jpg" alt="bash base64 encode and decode - example 1"></p><p>結果是經過 Base64 編碼後的字符串。</p><h4 id="解釋" tabindex="-1">解釋 <a class="header-anchor" href="#解釋" aria-label="Permalink to “解釋”">​</a></h4><p>Base64 編碼方法使用下面的幾個步驟來轉換輸入的數據。首先，每個輸入字符轉換為 8 位二進制值，接着，二進制字符串拆分為一組組 6 位的二進制值，然後，每個 6 位的二進制值被轉換為十進制值。</p><p>最後，每個十進制值都通過 Base64 編碼索引錶轉換為 Base64 字符。</p><p>在上面的示例中，第一個字符 <code>d</code> 被轉換為二進制 <code>01100100</code>。前 6 位是 <code>011001</code>，轉換為十進制是 <code>25</code>。<code>25</code> 在 Base64 編碼索引表中對應着 <code>Z</code>。整個輸入的文本流都像如此編碼。請參閲以下編碼過程的示例。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/11/Base64-Encode-and-Decode-inner-working.png" alt="Base64 Encode and Decode – inner working"></p><h4 id="示例-2-基本解碼" tabindex="-1">示例 2：基本解碼 <a class="header-anchor" href="#示例-2-基本解碼" aria-label="Permalink to “示例 2：基本解碼”">​</a></h4><p>要解碼字符串，需要將編碼值傳遞給 <code>base64</code> 命令，選項為 <code>--decode</code>，它將輸出你之前輸入的字符串。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/11/bash-base64-encode-and-decode-example-2-decode-the-same-example.jpg" alt="bash base64 encode and decode - example 2 (decode the same example)"></p><h4 id="示例-3-對文本文件進行編碼" tabindex="-1">示例 3：對文本文件進行編碼 <a class="header-anchor" href="#示例-3-對文本文件進行編碼" aria-label="Permalink to “示例 3：對文本文件進行編碼”">​</a></h4><p>示例 1 中的同一命令也可用於編碼文本文件，並將輸出重定向到另一個文本文件。方法如下。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>base64 example3.txt &gt; example3-encoded.txt</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/11/Encode-a-text-file.png" alt="Encode a text file"></p><h4 id="示例-4-對文本文件進行解碼" tabindex="-1">示例 4：對文本文件進行解碼 <a class="header-anchor" href="#示例-4-對文本文件進行解碼" aria-label="Permalink to “示例 4：對文本文件進行解碼”">​</a></h4><p>要解碼使用 Base64 編碼的文本文件，只需使用 <code>--decode</code> 或 <code>-d</code> 選項，並傳遞文本文件名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>base64 -d example3-encoded.txt</span></span></code></pre></div><h4 id="示例-5-對用户輸入的數據進行編碼" tabindex="-1">示例 5：對用户輸入的數據進行編碼 <a class="header-anchor" href="#示例-5-對用户輸入的數據進行編碼" aria-label="Permalink to “示例 5：對用户輸入的數據進行編碼”">​</a></h4><p>使用 Bash shell 編程，你可以通過終端接收用户的輸入，並對其進行 Base64 編碼。你需要先編寫一個簡單的 shell 腳本，並在授予可執行權限後執行。</p><p>以下就是一個簡單的示例，它從用户那裏獲得輸入，然後進行 Base64 編碼，最終顯示編碼的字符串。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>#Sample program to take input, encode to base64 and display on terminal</span></span>
<span class="line"><span>#Example by www.debugpoint.com</span></span>
<span class="line"><span>echo &quot;Enter text for encoding to base64:&quot;</span></span>
<span class="line"><span>read input_text</span></span>
<span class="line"><span>output_text=\`echo -n $input_text | base64\`</span></span>
<span class="line"><span>echo &quot;The Base64 Encoded text is: $output_text&quot;</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/11/Custom-input-base64-encode-and-decode-using-script.png" alt="Custom input - base64 encode and decode using script"></p><h4 id="示例-6-用-base64-進行簡單的身份認證" tabindex="-1">示例 6：用 Base64 進行簡單的身份認證 <a class="header-anchor" href="#示例-6-用-base64-進行簡單的身份認證" aria-label="Permalink to “示例 6：用 Base64 進行簡單的身份認證”">​</a></h4><p>你可以運用上述的編碼和解碼方法，實現一個簡單的身份驗證系統。你可以讓用户輸入密碼或密碼，然後將密碼存儲在文件中。或者進行實時比較。</p><p>如果存儲的編碼字符串與用户輸入的文本再編碼的字符串相匹配，則用户可以通過驗證。雖然這是一種檢查身份驗證的很簡單的方法，但有時這對一些簡單的業務案例很有用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>#Sample program to take input, encode to base64 and display on terminal</span></span>
<span class="line"><span>#Example by www.debugpoint.com</span></span>
<span class="line"><span>echo &quot;Type your password&quot;</span></span>
<span class="line"><span>read pwd1</span></span>
<span class="line"><span>decoded_text=\`echo &#39;U2lsZW5jZSBpcyBnb2xkZW4h&#39; | base64 --decode\`</span></span>
<span class="line"><span>if [[ $pwd1 == $decoded_text ]]</span></span>
<span class="line"><span>then</span></span>
<span class="line"><span>    echo &quot;You are a valid user.&quot;</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>    echo &quot;You are NOT a valid user.&quot;</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/11/A-Simple-Authentication-using-bash-base64.png" alt="A Simple Authentication using bash base64"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3>`,45)),d("p",null,[e[1]||(e[1]=a("我希望你能通過這些示例，學會 ",-1)),t(s,{href:"https://linux.die.net/man/1/base64"},{default:n(()=>[...e[0]||(e[0]=[a("Base64",-1)])]),_:1}),e[2]||(e[2]=a(" 編碼和解碼的基礎知識。此外，你也瞭解到 Base64 的內部編碼方式。如果這對你很有幫助，或你還需要有關此主題的其他教程，請在下面的評論區中告訴我吧。",-1))]),e[19]||(e[19]=d("hr",null,null,-1)),d("p",null,[e[4]||(e[4]=a("via: ",-1)),t(s,{href:"https://www.debugpoint.com/bash-base64-encode-decode/"},{default:n(()=>[...e[3]||(e[3]=[a("https://www.debugpoint.com/bash-base64-encode-decode/",-1)])]),_:1})]),d("p",null,[e[9]||(e[9]=a("作者：",-1)),t(s,{href:"https://www.debugpoint.com/author/admin1/"},{default:n(()=>[...e[5]||(e[5]=[a("Arindam",-1)])]),_:1}),e[10]||(e[10]=a(" 選題：",-1)),t(s,{href:"https://github.com/lkxed"},{default:n(()=>[...e[6]||(e[6]=[a("lkxed",-1)])]),_:1}),e[11]||(e[11]=a(" 譯者：",-1)),t(s,{href:"https://github.com/chai001125"},{default:n(()=>[...e[7]||(e[7]=[a("chai001125",-1)])]),_:1}),e[12]||(e[12]=a(" 校對：",-1)),t(s,{href:"https://github.com/wxy"},{default:n(()=>[...e[8]||(e[8]=[a("wxy",-1)])]),_:1})]),d("p",null,[e[15]||(e[15]=a("本文由 ",-1)),t(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[13]||(e[13]=[a("LCTT",-1)])]),_:1}),e[16]||(e[16]=a(" 原創編譯，",-1)),t(s,{href:"https://linux.cn/"},{default:n(()=>[...e[14]||(e[14]=[a("Linux中國",-1)])]),_:1}),e[17]||(e[17]=a(" 榮譽推出",-1))])])}const B=i(r,[["render",h]]);export{w as __pageData,B as default};
